  (894,'govt_technical','sol-concept','concept',1,'विलयन और मिश्रण — SSC JE / RRB JE',$j${"note":"JE में मोलरता और द्रव्यमान प्रतिशत के सूत्र अक्सर पूछे जाते हैं।","text":"विलयन में विलेय (solute) विलायक (solvent) में घुला रहता है और कण दिखाई नहीं देते। कोलॉइड में कण बड़े होते हैं पर छाने नहीं जाते। निलंबन (suspension) में कण बड़े होते हैं और बैठ जाते हैं। मोलरता M = मोल / लीटर।"}$j$),
  (894,'govt_technical','sol-formula','formula',2,'मोलरता का सूत्र',$j${"formula":"M = (विलेय के मोल) / (विलयन का आयतन, L)","explanation":"M = मोलरता (mol/L), मोल = द्रव्यमान (g) / मोलर द्रव्यमान (g/mol)"}$j$),
  (894,'govt_technical','sol-example','example',3,'Numerical (JE style)',$j${"question":"NaOH (मोलर द्रव्यमान 40 g/mol) के 4 g को 500 mL पानी में घोला गया। मोलरता कितनी है?","solution":"मोल = 4/40 = 0.1; आयतन = 0.5 L; M = 0.1/0.5 = 0.2 M","answer":"0.2 M"}$j$),
  (894,'govt_technical','sol-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"जिस मिश्रण में कण छाने नहीं जा सकते पर बैठते भी नहीं, वह क्या है?","options":["कोलॉइड","विलयन","निलंबन","यौगिक"],"answer":0,"explanation":"कोलॉइड में कण बड़े होते हैं पर स्थिर रहते हैं और छाने नहीं जाते।"},{"q":"विलयन की मोलरता का मात्रक क्या है?","options":["mol/L","g/mL","% (w/w)","ppm"],"answer":0,"explanation":"मोलरता का मात्रक mol/L है।"}]}$j$),
  (894,'govt_basic','sol-concept','concept',1,'विलयन और मिश्रण',$j${"note":"परीक्षा में चीनी-पानी जैसे विलयन के उदाहरण पूछे जाते हैं।","text":"चीनी को पानी में घोलने पर बना मिश्रण विलयन है। इसमें चीनी (विलेय) और पानी (विलायक) होते हैं। विलयन पारदर्शी होता है और उसके कण दिखाई नहीं देते।"}$j$),
  (894,'govt_basic','sol-formula','formula',2,'द्रव्यमान प्रतिशत',$j${"formula":"द्रव्यमान % = (विलेय का द्रव्यमान / विलयन का द्रव्यमान) × 100","explanation":"विलयन का द्रव्यमान = विलेय + विलायक"}$j$),
  (894,'govt_basic','sol-example','example',3,'उदाहरण',$j${"question":"10 g नमक को 90 g पानी में घोला गया। नमक का द्रव्यमान प्रतिशत कितना है?","solution":"विलयन = 10 + 90 = 100 g; % = 10/100 × 100 = 10%","answer":"10%"}$j$),
  (894,'govt_basic','sol-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"चीनी को पानी में घोलने पर बना मिश्रण क्या कहलाता है?","options":["विलयन","निलंबन","कोलॉइड","यौगिक"],"answer":0,"explanation":"चीनी और पानी का समांगी मिश्रण विलयन है।"},{"q":"विलयन में जो पदार्थ घुलता है, उसे क्या कहते हैं?","options":["विलेय (solute)","विलायक (solvent)","उत्प्रेरक","अवशेष"],"answer":0,"explanation":"घुलने वाला पदार्थ विलेय (solute) कहलाता है।"}]}$j$),
