  -- 895 Electrochemistry
  (895,'govt_technical','elch-concept','concept',1,'विद्युत रसायन — SSC JE / RRB JE',$j${"note":"JE में फैराडे के नियम और 1 F = 96500 C अक्सर पूछे जाते हैं।","text":"फैराडे का पहला नियम: निक्षेपित पदार्थ का द्रव्यमान आवेश के समानुपाती होता है। m = Z·I·t। 1 फैराडे (F) = 96500 C आवेश, जो 1 ग्राम तुल्यांक पदार्थ जमा करता है। गैलवेनिक सेल में ऑक्सीकरण एनोड पर और अपचयन कैथोड पर होता है।"}$j$),
  (895,'govt_technical','elch-formula','formula',2,'फैराडे का पहला नियम',$j${"formula":"m = Z × I × t","explanation":"m = निक्षेपित द्रव्यमान (g), Z = विद्युत-रासायनिक तुल्यांक (g/C), I = धारा (A), t = समय (s) · 1 F = 96500 C"}$j$),
  (895,'govt_technical','elch-example','example',3,'Numerical (JE style)',$j${"question":"2 A धारा 1930 सेकंड तक प्रवाहित होती है। कितना आवेश गुजरता है और यह कितने फैराडे के बराबर है?","solution":"Q = I × t = 2 × 1930 = 3860 C; फैराडे में = 3860 / 96500 = 0.04 F","answer":"3860 C, 0.04 F"}$j$),
  (895,'govt_technical','elch-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"1 फैराडे आवेश का मान कितना है?","options":["96500 C","9650 C","1000 C","6.02×10²³ C"],"answer":0,"explanation":"1 फैराडे = 96500 कूलॉम।"},{"q":"गैलवेनिक सेल में ऑक्सीकरण किस इलेक्ट्रोड पर होता है?","options":["एनोड","कैथोड","विद्युत अपघट्य","सेतु"],"answer":0,"explanation":"ऑक्सीकरण एनोड पर होता है और इलेक्ट्रॉन बाहर निकलते हैं।"}]}$j$),
  (895,'govt_basic','elch-concept','concept',1,'विद्युत रसायन',$j${"note":"परीक्षा में बैटरी और इलेक्ट्रोप्लेटिंग के उदाहरण पूछे जाते हैं।","text":"विद्युत रसायन में रासायनिक ऊर्जा और विद्युत ऊर्जा का आपसी बदलाव होता है। बैटरी रासायनिक ऊर्जा को विद्युत में बदलती है। इलेक्ट्रोप्लेटिंग विद्युत धारा से एक धातु की परत दूसरी पर चढ़ाने की प्रक्रिया है।"}$j$),
  (895,'govt_basic','elch-formula','formula',2,'फैराडे का नियम (सरल रूप)',$j${"formula":"निक्षेपित द्रव्यमान ∝ आवेश","explanation":"धारा और समय जितने अधिक, उतना अधिक पदार्थ जमा होता है"}$j$),
  (895,'govt_basic','elch-example','example',3,'उदाहरण',$j${"question":"इलेक्ट्रोप्लेटिंग में धारा बढ़ाने पर जमा होने वाला पदार्थ कैसे बदलता है?","solution":"फैराडे के नियम के अनुसार आवेश बढ़ने पर द्रव्यमान बढ़ता है","answer":"बढ़ता है"}$j$),
  (895,'govt_basic','elch-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"बैटरी किस ऊर्जा को विद्युत ऊर्जा में बदलती है?","options":["रासायनिक ऊर्जा","यांत्रिक ऊर्जा","ध्वनि ऊर्जा","प्रकाश ऊर्जा"],"answer":0,"explanation":"बैटरी में रासायनिक अभिक्रिया से विद्युत ऊर्जा मिलती है।"},{"q":"इलेक्ट्रोप्लेटिंग किसका उदाहरण है?","options":["विद्युत अपघटन","वाष्पन","गलन","संघनन"],"answer":0,"explanation":"इलेक्ट्रोप्लेटिंग विद्युत अपघटन की एक प्रक्रिया है।"}]}$j$),
