  -- 896 Fuels & Combustion
  (896,'govt_technical','fuel-concept','concept',1,'ईंधन और दहन — SSC JE / RRB JE',$j${"note":"JE में कैलोरिफिक वैल्यू और अच्छे ईंधन के गुण अक्सर पूछे जाते हैं।","text":"दहन में ईंधन ऑक्सीजन से जलकर ऊष्मा देता है। ईंधन का कैलोरिफिक वैल्यू प्रति इकाई द्रव्यमान से निकली ऊष्मा है (kJ/kg)। अच्छे ईंधन में कैलोरिफिक वैल्यू अधिक, ज्वलन ताप कम और धुआँ कम होता है।"}$j$),
  (896,'govt_technical','fuel-formula','formula',2,'ऊष्मा की गणना',$j${"formula":"Q = m × CV","explanation":"Q = कुल ऊष्मा (kJ), m = ईंधन का द्रव्यमान (kg), CV = कैलोरिफिक वैल्यू (kJ/kg)"}$j$),
  (896,'govt_technical','fuel-example','example',3,'Numerical (JE style)',$j${"question":"कैलोरिफिक वैल्यू 50000 kJ/kg वाले 2 kg ईंधन के जलने से कितनी ऊष्मा निकलेगी?","solution":"Q = 2 × 50000 = 100000 kJ","answer":"100000 kJ"}$j$),
  (896,'govt_technical','fuel-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"12 kg कार्बन के पूरी तरह जलने पर कितने kg CO₂ बनती है?","options":["44 kg","12 kg","22 kg","32 kg"],"answer":0,"explanation":"C + O₂ → CO₂; 12 g C से 44 g CO₂ बनती है, इसलिए 12 kg से 44 kg।"},{"q":"अच्छे ईंधन के लिए ज्वलन ताप कैसा होना चाहिए?","options":["कम","बहुत अधिक","शून्य","ऋणात्मक"],"answer":0,"explanation":"कम ज्वलन ताप वाला ईंधन आसानी से जलता है।"}]}$j$),
  (896,'govt_basic','fuel-concept','concept',1,'ईंधन और दहन',$j${"note":"परीक्षा में LPG, कोयला और लकड़ी के उदाहरण पूछे जाते हैं।","text":"लकड़ी, कोयला, LPG और पेट्रोल ईंधन हैं। दहन के लिए ईंधन, ऑक्सीजन और ऊष्मा (ज्वलन ताप) तीनों चाहिए। यह अग्नि त्रिभुज कहलाता है।"}$j$),
  (896,'govt_basic','fuel-formula','formula',2,'दहन का सरल समीकरण',$j${"formula":"C + O₂ → CO₂ + ऊष्मा","explanation":"कार्बन युक्त ईंधन जलकर CO₂ और ऊष्मा देता है"}$j$),
  (896,'govt_basic','fuel-example','example',3,'उदाहरण',$j${"question":"आग बुझाने के लिए पानी डालने से आग किस चीज़ की कमी से बुझती है?","solution":"पानी ईंधन को ज्वलन ताप से नीचे ठंडा करता है, इसलिए दहन रुक जाता है","answer":"ज्वलन ताप (ऊष्मा)"}$j$),
  (896,'govt_basic','fuel-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"दहन के लिए इनमें से कौन जरूरी नहीं है?","options":["नाइट्रोजन","ईंधन","ऑक्सीजन","ऊष्मा (ज्वलन ताप)"],"answer":0,"explanation":"दहन के लिए ईंधन, ऑक्सीजन और ऊष्मा चाहिए; नाइट्रोजन आवश्यक नहीं।"},{"q":"LPG किस प्रकार का ईंधन है?","options":["द्रवीकृत पेट्रोलियम गैस","कोयला","लकड़ी","सौर ऊर्जा"],"answer":0,"explanation":"LPG का पूरा नाम Liquefied Petroleum Gas है।"}]}$j$),
