  -- 897 Polymers & Plastics
  (897,'govt_technical','poly-concept','concept',1,'बहुलक (Polymers) — SSC JE / RRB JE',$j${"note":"JE में योगात्मक और संघनन बहुलकीकरण के उदाहरण अक्सर पूछे जाते हैं।","text":"बहुलक में छोटे अणु (मोनोमर) दोहराव में जुड़कर बड़ा अणु बनाते हैं। योगात्मक बहुलकीकरण में मोनोमर बिना अणु निकाले जुड़ते हैं (पॉलिथीन)। संघनन बहुलकीकरण में जुड़ते समय छोटा अणु (जैसे पानी) निकलता है (नायलॉन)। ऊष्मा-सुनम्य (thermoplastic) बार-बार गलते हैं, ऊष्मा-दृढ़ (thermosetting) नहीं।"}$j$),
  (897,'govt_technical','poly-formula','formula',2,'पॉलिथीन का बहुलकीकरण',$j${"formula":"n CH₂=CH₂ → (−CH₂−CH₂−)ₙ","explanation":"n = मोनोमर की संख्या (एथिलीन), जोड़ से बना पॉलिथीन · कोई अणु नहीं निकलता"}$j$),
  (897,'govt_technical','poly-example','example',3,'Numerical (JE style)',$j${"question":"एथिलीन (C₂H₄, मोलर द्रव्यमान 28 g/mol) के 1000 मोनोमर जुड़कर पॉलिथीन बने, तो उसका अनुमानित मोलर द्रव्यमान कितना होगा?","solution":"लगभग 1000 × 28 = 28000 g/mol","answer":"लगभग 28000 g/mol"}$j$),
  (897,'govt_technical','poly-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"नायलॉन किस प्रकार के बहुलकीकरण से बनता है?","options":["संघनन","योगात्मक","आयनिक","प्रतिस्थापन"],"answer":0,"explanation":"नायलॉन संघनन बहुलकीकरण से बनता है, जिसमें छोटा अणु (पानी) निकलता है।"},{"q":"बैकेलाइट (Bakelite) किस प्रकार का प्लास्टिक है?","options":["ऊष्मा-दृढ़ (thermosetting)","ऊष्मा-सुनम्य (thermoplastic)","रबर","धातु"],"answer":0,"explanation":"बैकेलाइट एक बार ढलने के बाद दोबारा नहीं गलता, इसलिए ऊष्मा-दृढ़ है।"}]}$j$),
  (897,'govt_basic','poly-concept','concept',1,'बहुलक और प्लास्टिक',$j${"note":"परीक्षा में पॉलिथीन, PVC और नायलॉन के उपयोग पूछे जाते हैं।","text":"प्लास्टिक बहुलक से बनते हैं। पॉलिथीन थैलियों और बोतलों में, PVC पाइपों में और नायलॉन कपड़ों में प्रयोग होता है। प्लास्टिक हल्के, टिकाऊ और सस्ते होते हैं, पर पर्यावरण में आसानी से नहीं सड़ते।"}$j$),
  (897,'govt_basic','poly-formula','formula',2,'मोनोमर और बहुलक',$j${"formula":"मोनोमर (छोटा अणु) + मोनोमर + ... → बहुलक","explanation":"मोनोमर को दोहराने वाली इकाई भी कहते हैं"}$j$),
  (897,'govt_basic','poly-example','example',3,'उदाहरण',$j${"question":"पॉलिथीन थैली किसका बहुलक है?","solution":"पॉलिथीन एथिलीन (मोनोमर) के बहुलकीकरण से बनती है","answer":"एथिलीन"}$j$),
