  (898,'govt_basic','corr-concept','concept',1,'जंग',$j${"note":"परीक्षा में जंग रोकने के उपाय पूछे जाते हैं।","text":"लोहे पर हवा और नमी से लगने वाली लाल-भूरी परत को जंग कहते हैं। जंग लोहे को कमजोर कर देती है। पेंट करना और जस्ता चढ़ाना जंग रोकने के आम तरीके हैं।"}$j$),
  (898,'govt_basic','corr-formula','formula',2,'जंग की शर्तें',$j${"formula":"जंग = लोहा + ऑक्सीजन + पानी (नमी)","explanation":"इनमें से एक भी न हो तो जंग नहीं लगती"}$j$),
